// Generated by prepare_submissions.py from submissions.json. Edit the template, then regenerate.
// Import chunk @@CHUNK@@: creates its submission items with every submission_* attribute in one native batch.
// Run each chunk once, in any order, after 30-create-submissions.
assert session.sessionResource.URI.toString().toLowerCase().contains('/fsae-2027-electric-arcadia/'): 'Only the disposable acceptance project is permitted'
assert api.layer('SA').system.summary == 'FSAE2027:bootstrap-v1': 'Missing the acceptance project marker'
def req = api.requirements()
assert req.available() && req.viewpointEnabled()
def module = req.find(@@MODULE_ID@@)
assert module != null: 'Run 30-create-submissions first'
def folders = [:]
def iterator = module.eAllContents()
while (iterator.hasNext()) {
    def element = iterator.next()
    if (element.eClass().name == 'Folder') folders[element.ReqIFIdentifier] = element
}
def common = @@COMMON@@
def sections = @@SECTIONS@@
def before = req.requirements(module).collect { it.ReqIFIdentifier } as Set
assert sections.every { section -> section.records.every { !before.contains(it.identifier) } }: 'This chunk was already imported; run 40-verify-submissions instead'
api.batch('Import submission items ' + @@CHUNK@@) {
    sections.each { section ->
        def folder = folders[section.folder]
        assert folder != null: 'Missing section folder ' + section.folder
        req.importRequirements(folder, section.records.collect { record -> record + [attributes: common + record.attributes] })
    }
}
def after = req.requirements(module).size()
assert after == before.size() + @@CHUNK_COUNT@@
log.info('Submission import chunk ' + @@CHUNK@@ + ' applied: ' + after + ' items in the module.')
return [chunk: @@CHUNK@@, imported: @@CHUNK_COUNT@@, items_in_module: after]
